function i(t){if(!t)return"0 B";const r=["B","KB","MB","GB"],o=Math.floor(Math.log(t)/Math.log(1024));return`${(t/1024**o).toFixed(o?1:0)} ${r[o]}`}function e(t){return t?new Date(t).toLocaleDateString(void 0,{year:"numeric",month:"short",day:"numeric"}):"—"}function f(t){if(!t)return"0m";const r=Math.floor(t/3600),o=Math.floor(t%3600/60);return r?`${r}h ${o}m`:`${o}m`}function u(t){const r=Date.now()-new Date(t).getTime(),o=Math.floor(r/6e4);if(o<1)return"just now";if(o<60)return`${o}m ago`;const n=Math.floor(o/60);if(n<24)return`${n}h ago`;const a=Math.floor(n/24);return a<30?`${a}d ago`:e(t)}export{i as a,e as b,f,u as t};
